from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest, ContentFormat
from azure.core.credentials import AzureKeyCredential
import os
import json

def normalize_expense_fields(document_path: str) -> dict:
    """
    Normalizes extracted expense fields from an invoice document into a standard JSON schema.

    Standard schema:
    {
        "vendor": str,
        "invoice_date": str (YYYY-MM-DD),
        "due_date": str (YYYY-MM-DD),
        "invoice_number": str,
        "total_amount": float,
        "currency": str,
        "line_items": [
            {
                "description": str,
                "quantity": float,
                "unit_price": float,
                "amount": float
            }
        ]
    }
    """
    endpoint = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError("Azure Document Intelligence endpoint and key must be set in environment variables")

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-invoice",
            analyze_request=AnalyzeDocumentRequest(bytes_source=f.read()),
            content_type="application/octet-stream",
            output_content_format=ContentFormat.MARKDOWN
        )

    result = poller.result()

    normalized = {
        "vendor": None,
        "invoice_date": None,
        "due_date": None,
        "invoice_number": None,
        "total_amount": None,
        "currency": None,
        "line_items": []
    }

    if result.documents:
        invoice = result.documents[0].fields

        if invoice.get("VendorName"):
            normalized["vendor"] = invoice["VendorName"].value.value_string
        if invoice.get("InvoiceDate"):
            normalized["invoice_date"] = invoice["InvoiceDate"].value.value_date.isoformat()
        if invoice.get("DueDate"):
            normalized["due_date"] = invoice["DueDate"].value.value_date.isoformat()
        if invoice.get("InvoiceId"):
            normalized["invoice_number"] = invoice["InvoiceId"].value.value_string
        if invoice.get("Total"):
            normalized["total_amount"] = float(invoice["Total"].value.value_currency.amount)
        if invoice.get("Total") and invoice["Total"].value.value_currency.currency_code:
            normalized["currency"] = invoice["Total"].value.value_currency.currency_code

        if invoice.get("Items"):
            for item in invoice["Items"].value.value_array:
                line_item = {
                    "description": None,
                    "quantity": None,
                    "unit_price": None,
                    "amount": None
                }
                if item.value.get("Description"):
                    line_item["description"] = item.value["Description"].value.value_string
                if item.value.get("Quantity"):
                    line_item["quantity"] = float(item.value["Quantity"].value.value_number)
                if item.value.get("UnitPrice"):
                    line_item["unit_price"] = float(item.value["UnitPrice"].value.value_currency.amount)
                if item.value.get("Amount"):
                    line_item["amount"] = float(item.value["Amount"].value.value_currency.amount)
                normalized["line_items"].append(line_item)

    return normalized
